void check(bool v,const char* message){if(!v)throw std::runtime_error(message);}
template<class E=std::exception,class F>void rejects(F f){try{f();}catch(const E&){return;}throw std::runtime_error("Expected unmixed fluorescence refusal");}
void close(double value,double expected){check(std::isfinite(value) && std::abs(value-expected)<=1e-11*std::max(1.,std::abs(expected)),"Unmixed compartment differs from independent oracle");}
std::string bytes(const fs::path& p){std::ifstream in(p,std::ios::binary);return {std::istreambuf_iterator<char>(in),{}};}
void field(const fs::path& path,std::uint16_t a,std::uint16_t b){qpx_test::raw_pixel_tiff_fixture(path,15,9);std::fstream out(path,std::ios::binary|std::ios::in|std::ios::out);out.seekp(160);for(int i=0;i<135;++i)for(auto v:{a,b}){out.put(char(v&255));out.put(char(v>>8));}out.close();check(bool(out),"Write analytical unmixing fields");}
LinearMixingMatrix matrix(const Document& doc){const auto m=doc.server()->raw_metadata();LinearMixingMatrix p;p.inputs={{0,m->channel_names.at(0)},{1,m->channel_names.at(1)}};p.components={"DNA","Marker"};p.coefficients={1,-0.0,2,1};return p;}
MarkerRule rule(const std::string& id){MarkerRule p;p.domain="qpx.linear-unmixed-samples/1";p.unmix_record=id;p.gates={{"Marker",1}};p.gates[0].comparison=MarkerComparison::Less;p.nodes={{MarkerOperation::Gate,0,{}}};return p;}
